import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, sin, cos } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();
  const cleanupTasks = [];

  // 1. STAGE BACKDROP (to prevent "FLAT_VOID" defect, designed-for-dark styled gradient)
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial({
    depthWrite: false,
    transparent: true,
    opacity: 0.85
  });

  // TSL Gradient Surface Node with subtle engineered grain
  const uvNode = uv();
  const gradient = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10 (Surface)
    vec3(0.086, 0.086, 0.114), // Darker transition
    uvNode.y
  );
  const grain = sin(uvNode.x.mul(1200.0)).mul(cos(uvNode.y.mul(1200.0))).mul(0.015);
  bgMat.colorNode = gradient.add(grain);

  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.1);
  group.add(bgMesh);
  cleanupTasks.push(() => {
    bgGeo.dispose();
    bgMat.dispose();
  });

  // 2. TEXTURED SPRITE / CARD BASE (Atlas size: 512x320 -> Aspect 1.6)
  const cardWidth = 3.2;
  const cardHeight = 2.0;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);

  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    transparentBorder: true,
    depthWrite: true
  });

  // Apply subtle local grain overlay onto the sprite texture
  const baseUv = uv();
  const cardGrain = sin(baseUv.x.mul(800.0)).mul(cos(baseUv.y.mul(800.0))).mul(0.02);
  cardMat.colorNode = cardGrain;

  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);
  cleanupTasks.push(() => {
    cardGeo.dispose();
    cardMat.dispose();
  });

  // Load Asset Texture if provided
  const textureUrl = config.imageUrl || config.intent?.visualSpec?.imageUrl;
  if (textureUrl) {
    ctx.textureLoader.loadTexture(textureUrl).then((tex) => {
      cardMat.colorNode = cardMat.colorNode.add(tex);
      cardMat.needsUpdate = true;
    }).catch(err => console.warn('Failed loading card texture:', err));
  }

  // 3. TEXT LAYER (MSDF Engine-level Text rendering)
  // Get primary title from visualSpec or hardcoded default
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primaryText = items.find(i => i.role === 'headline')?.text || 'Collection 1';

  const textNode = ctx.fontAtlas.createText(primaryText, {
    fontSize: 0.28,
    color: '#e8ecf2', // Paper
    align: 'center'
  });
  // Position text nicely layered on top of the card
  textNode.position.set(0, -0.1, 0.1);
  group.add(textNode);

  // 4. BILLBOARD BEHAVIOR (Look-at camera on Z-plane)
  const targetCamPos = new Vector3();
  const onBeforeRender = (renderer, scene, camera) => {
    if (camera) {
      camera.getWorldPosition(targetCamPos);
      // Neutralize local pitch/roll to keep looking straight or pivot gently on Y-axis
      targetCamPos.y = group.position.y; 
      group.lookAt(targetCamPos);
    }
  };

  // Attach renderer updater to group
  group.onBeforeRender = onBeforeRender;

  // 5. ANIMATIONS (GSAP Entry settling)
  const timeline = gsap.timeline({ defaults: { ease: 'power4.out' } });

  // Set initial state
  group.position.y -= 0.15;
  group.scale.set(0.95, 0.95, 0.95);
  bgMat.opacity = 0;

  timeline.to(group.position, {
    y: '+=0.15',
    duration: 1.1,
  }, 0);

  timeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.2,
  }, 0);

  timeline.to(bgMat, {
    opacity: 0.85,
    duration: 0.8,
  }, 0.1);

  // Apply cinematic primitives (if any dynamic triggers are mapped in orchestration)
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        try {
          const res = ctx.primitives[prim.name](group, prim.params);
          if (res) activePrimitives.push(res);
        } catch (e) {
          console.warn(`Primitive ${prim.name} skipped:`, e);
        }
      }
    }
  }

  // 6. CLEANUP HOOK
  group.userData = {
    handlers: {},
    cleanup: () => {
      timeline.kill();
      activePrimitives.forEach(p => p.cleanup?.());
      cleanupTasks.forEach(task => task());
    }
  };

  return group;
}
